&lt;/li&gt;
&lt;li data-local-id=&quot;2ffe6c7d-ee0d-47d9-b50b-68aa9526beb6&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
