&lt;/li&gt;
&lt;li data-local-id=&quot;e6af16bf-7233-4e4a-99bd-e15f1b0c5a0f&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
