&lt;/li&gt;
&lt;li data-local-id=&quot;8739a04b-ad7d-4bc1-864f-daac5d8820db&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
