&lt;/li&gt;
&lt;li data-local-id=&quot;1af54ff0-285f-4221-b748-ca239c061fb1&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
