&lt;/li&gt;
&lt;li data-local-id=&quot;39774196-7a65-42f1-86dc-4ef7b29f7d51&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
