&lt;ul&gt;
&lt;li data-local-id=&quot;d8af26a0-fc39-4523-8b86-f203ecdb6359&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
