&lt;li data-local-id=&quot;54b23537-328e-4cb6-9b0e-69e51d7d6835&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
