&lt;/li&gt;
&lt;li data-local-id=&quot;bbe39722-d580-4e39-9766-17c83fa68656&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
