&lt;/li&gt;
&lt;li data-local-id=&quot;a03be5e1-89d5-4507-a105-bc9ac9aa299e&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
