&lt;/li&gt;
&lt;li data-local-id=&quot;03001173-44d2-45d8-b065-8e79a7e4c516&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
