&lt;li data-local-id=&quot;b5e81c69-5c04-4f81-8659-6008da61e1e9&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
