&lt;li data-local-id=&quot;a8f2de3d-5d4d-4062-bb82-c9cf1b105360&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
